require dirname(__DIR__).'/app/bootstrap.php';if(admin_id())redirect_to('webyonet/');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$username=trim($_POST['username']??'');$password=(string)($_POST['password']??'');$ip=$_SERVER['REMOTE_ADDR']??'';$s=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE username=? AND ip_address=? AND created_at>=DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$s->execute([$username,$ip]);if((int)$s->fetchColumn()>=6){$error='Çok fazla hatalı deneme. 15 dakika sonra tekrar deneyin.';}else{$s=db()->prepare('SELECT * FROM admins WHERE username=? AND is_active=1 LIMIT 1');$s->execute([$username]);$a=$s->fetch();if($a&&password_verify($password,$a['password_hash'])){$old=session_id();session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];db()->prepare('UPDATE admins SET last_login_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$a['id']]);db()->prepare('DELETE FROM login_attempts WHERE username=? AND ip_address=?')->execute([$username,$ip]);redirect_to('webyonet/');}else{db()->prepare('INSERT INTO login_attempts(username,ip_address,created_at) VALUES(?,?,NOW())')->execute([$username,$ip]);$error='Kullanıcı adı veya şifre hatalı.';}}}
